$ErrorActionPreference = 'Stop'
$root = 'g:\0.DỰ ÁN\Z.WEB_SITE\WEB-New-QuyNhon'
$fullPath = Join-Path $root '4.SOURCE-MẪU\sql\full.sql'
$patchDir = Join-Path $root 'sql\patches'
if (!(Test-Path -LiteralPath $patchDir)) { New-Item -ItemType Directory -Path $patchDir | Out-Null }
$patchPath = Join-Path $patchDir '20261010_sync_full_schema_stores_from_source_mau.sql'
$server = 'DESKTOP-PBMQQ03\SQLEXPRESS'
$db = 'W2023'
$user = 'THSTrong_Demo1'
$pass = '2026.@#wb.nw.01'
$full = Get-Content -LiteralPath $fullPath -Raw
# Normalize GO batches.
$batches = [regex]::Split($full, '(?im)^\s*GO\s*\d*\s*$')
# Current DB objects.
$tableQuery = "Set Nocount On; Select name From sys.tables Where schema_id = Schema_Id('dbo') Order By name;"
$procQuery = "Set Nocount On; Select name From sys.procedures Where schema_id = Schema_Id('dbo') Order By name;"
$columnQuery = "Set Nocount On; Select t.name + '.' + c.name From sys.tables t Inner Join sys.columns c on c.object_id = t.object_id Where t.schema_id = Schema_Id('dbo');"
$defaultQuery = "Set Nocount On; Select dc.name From sys.default_constraints dc Inner Join sys.tables t on t.object_id = dc.parent_object_id Where t.schema_id = Schema_Id('dbo');"
function Invoke-SqlList($query) {
    $out = & sqlcmd -S $server -d $db -U $user -P $pass -h -1 -W -Q $query
    if ($LASTEXITCODE -ne 0) { throw "sqlcmd failed: $query" }
    return @($out | Where-Object { $_ -and $_.Trim() -ne '' -and $_ -notmatch '^\(\d+ rows affected\)$' } | ForEach-Object { $_.Trim() })
}
$currentTables = New-Object 'System.Collections.Generic.HashSet[string]' ([StringComparer]::OrdinalIgnoreCase)
Invoke-SqlList $tableQuery | ForEach-Object { [void]$currentTables.Add($_) }
$currentProcs = New-Object 'System.Collections.Generic.HashSet[string]' ([StringComparer]::OrdinalIgnoreCase)
Invoke-SqlList $procQuery | ForEach-Object { [void]$currentProcs.Add($_) }
$currentColumns = New-Object 'System.Collections.Generic.HashSet[string]' ([StringComparer]::OrdinalIgnoreCase)
Invoke-SqlList $columnQuery | ForEach-Object { [void]$currentColumns.Add($_) }
$currentDefaults = New-Object 'System.Collections.Generic.HashSet[string]' ([StringComparer]::OrdinalIgnoreCase)
Invoke-SqlList $defaultQuery | ForEach-Object { [void]$currentDefaults.Add($_) }
# Collect table create blocks and default constraints.
$tableBlocks = @{}
$defaultBlocks = @()
$procedureBlocks = @()
foreach ($batch in $batches) {
    $trim = $batch.Trim()
    if ($trim -eq '') { continue }
    $tableMatch = [regex]::Match($trim, '(?is)^\s*(?:/\*.*?\*/\s*)?(?:SET\s+ANSI_NULLS\s+ON\s*)?(?:SET\s+QUOTED_IDENTIFIER\s+ON\s*)?CREATE\s+TABLE\s+\[dbo\]\.\[([^\]]+)\]')
    if ($tableMatch.Success) {
        $tableBlocks[$tableMatch.Groups[1].Value] = $trim
        continue
    }
    $defaultMatch = [regex]::Match($trim, '(?is)^\s*ALTER\s+TABLE\s+\[dbo\]\.\[([^\]]+)\]\s+ADD\s+CONSTRAINT\s+\[([^\]]+)\]')
    if ($defaultMatch.Success) {
        $defaultBlocks += [pscustomobject]@{ Table = $defaultMatch.Groups[1].Value; Constraint = $defaultMatch.Groups[2].Value; Sql = $trim }
        continue
    }
    $procMatch = [regex]::Match($trim, '(?is)^\s*(?:/\*.*?\*/\s*)?(?:SET\s+ANSI_NULLS\s+ON\s*)?(?:SET\s+QUOTED_IDENTIFIER\s+ON\s*)?CREATE\s+PROCEDURE\s+\[dbo\]\.\[([^\]]+)\]')
    if ($procMatch.Success) {
        $procedureBlocks += [pscustomobject]@{ Name = $procMatch.Groups[1].Value; Sql = $trim }
        continue
    }
}
# Parse columns from create table for existing tables and missing columns only.
function Split-TopLevelComma([string]$s) {
    $parts = New-Object System.Collections.Generic.List[string]
    $level = 0
    $start = 0
    for ($i = 0; $i -lt $s.Length; $i++) {
        $ch = $s[$i]
        if ($ch -eq '(') { $level++ }
        elseif ($ch -eq ')') { if ($level -gt 0) { $level-- } }
        elseif ($ch -eq ',' -and $level -eq 0) {
            $parts.Add($s.Substring($start, $i - $start).Trim())
            $start = $i + 1
        }
    }
    if ($start -lt $s.Length) { $parts.Add($s.Substring($start).Trim()) }
    return $parts
}
$sb = New-Object System.Text.StringBuilder
[void]$sb.AppendLine('/*')
[void]$sb.AppendLine('Patch  : Đồng bộ cấu trúc bảng và stored procedure từ 4.SOURCE-MẪU/sql/full.sql')
[void]$sb.AppendLine('Date   : 2026-10-10')
[void]$sb.AppendLine('Module : InformationWeb')
[void]$sb.AppendLine('DB     : W2023')
[void]$sb.AppendLine('Ghi chú: Script an toàn, không drop bảng/cột, không xóa dữ liệu. Stored procedure được drop/create theo baseline mẫu.')
[void]$sb.AppendLine('*/')
[void]$sb.AppendLine('Set Xact_Abort Off')
[void]$sb.AppendLine('Go')
$missingTables = New-Object System.Collections.Generic.List[string]
$missingColumns = New-Object System.Collections.Generic.List[string]
foreach ($entry in $tableBlocks.GetEnumerator() | Sort-Object Name) {
    $tableName = $entry.Key
    $createSql = $entry.Value
    if (!$currentTables.Contains($tableName)) {
        $missingTables.Add($tableName)
        [void]$sb.AppendLine("Print N'Tạo bảng dbo.$tableName'")
        [void]$sb.AppendLine($createSql)
        [void]$sb.AppendLine('Go')
    } else {
        $bodyMatch = [regex]::Match($createSql, '(?is)CREATE\s+TABLE\s+\[dbo\]\.\[[^\]]+\]\s*\((.*)\)\s+ON\s+\[PRIMARY\]')
        if ($bodyMatch.Success) {
            $defs = Split-TopLevelComma $bodyMatch.Groups[1].Value
            foreach ($def in $defs) {
                $colMatch = [regex]::Match($def, '(?is)^\s*\[([^\]]+)\]\s+(.+)$')
                if (!$colMatch.Success) { continue }
                $colName = $colMatch.Groups[1].Value
                $colDef = $def.Trim()
                $key = "$tableName.$colName"
                if (!$currentColumns.Contains($key)) {
                    $missingColumns.Add($key)
                    [void]$sb.AppendLine("If Col_Length(N'[dbo].[$tableName]', N'$colName') Is Null")
                    [void]$sb.AppendLine('Begin')
                    [void]$sb.AppendLine("`tPrint N'Thêm cột dbo.$key'")
                    [void]$sb.AppendLine("`tAlter Table [dbo].[$tableName] Add $colDef")
                    [void]$sb.AppendLine('End')
                    [void]$sb.AppendLine('Go')
                }
            }
        }
    }
}
$missingDefaults = New-Object System.Collections.Generic.List[string]
foreach ($d in $defaultBlocks) {
    if ($currentTables.Contains($d.Table) -and !$currentDefaults.Contains($d.Constraint)) {
        $missingDefaults.Add($d.Constraint)
        [void]$sb.AppendLine("If Object_Id(N'[dbo].[$($d.Constraint)]', N'D') Is Null")
        [void]$sb.AppendLine('Begin')
        [void]$sb.AppendLine("`tPrint N'Thêm default constraint dbo.$($d.Constraint)'")
        [void]$sb.AppendLine("`t$($d.Sql)")
        [void]$sb.AppendLine('End')
        [void]$sb.AppendLine('Go')
    }
}
$procCount = 0
foreach ($p in $procedureBlocks | Sort-Object Name) {
    $procCount++
    [void]$sb.AppendLine("Print N'Đồng bộ store dbo.$($p.Name)'")
    [void]$sb.AppendLine("If Object_Id(N'[dbo].[$($p.Name)]', N'P') Is Not Null")
    [void]$sb.AppendLine("`tDrop Procedure [dbo].[$($p.Name)]")
    [void]$sb.AppendLine('Go')
    [void]$sb.AppendLine($p.Sql)
    [void]$sb.AppendLine('Go')
}
$summary = "-- Summary: MissingTables=$($missingTables.Count); MissingColumns=$($missingColumns.Count); MissingDefaults=$($missingDefaults.Count); Procedures=$procCount"
[void]$sb.Insert(0, $summary + [Environment]::NewLine)
[System.IO.File]::WriteAllText($patchPath, $sb.ToString(), [System.Text.Encoding]::UTF8)
Write-Host "PatchPath=$patchPath"
Write-Host $summary
Write-Host "MissingTables: $($missingTables -join ', ')"
Write-Host "MissingColumns: $($missingColumns -join ', ')"
Write-Host "MissingDefaults: $($missingDefaults.Count)"

