 namespace InformationWeb.Controls.InfoSection
 {
     public partial class N_TinTuc2 : System.Web.UI.UserControl
     {
+        private const int TopLimit = 6;
+        private const long ExcludeCareerCategoryId = 10481L;
+        protected string NewsDataJson = "[]";
         protected void Page_Load(object sender, EventArgs e)
         {
-
+            if (IsPostBack)
+                return;
+            BindNews();
+        }
+        private void BindNews()
+        {
+            try
+            {
+                INFO_Information objInfo = new INFO_Information();
+                DataTable dt = objInfo.GetDataTable("INFO_Information_List_NotCareer", "@Top", TopLimit, "@ExcludeCategoryId", ExcludeCareerCategoryId);
+                NewsDataJson = BuildNewsJson(dt);
+            }
+            catch (Exception ex)
+            {
+                new SystemError(SystemConfig.ConnectionString, "N_TinTuc2: Lỗi load tin tức động", ex);
+                NewsDataJson = "[]";
+            }
+        }
+        private string BuildNewsJson(DataTable dt)
+        {
+            if (dt == null || dt.Rows.Count == 0)
+                return "[]";
+            StringBuilder sb = new StringBuilder();
+            sb.Append("[");
+            for (int i = 0; i < dt.Rows.Count; i++)
+            {
+                DataRow row = dt.Rows[i];
+                if (i > 0)
+                    sb.Append(",");
+                sb.Append("{");
+                sb.Append("\"date\":\"").Append(JsonEncode(GetDateDisplay(row["CreatedDate"]))).Append("\",");
+                sb.Append("\"comments\":\"Bình luận\",");
+                sb.Append("\"title\":\"").Append(JsonEncode(GetString(row, "Title"))).Append("\",");
+                sb.Append("\"description\":\"").Append(JsonEncode(GetString(row, "Description"))).Append("\",");
+                sb.Append("\"detailUrl\":\"").Append(JsonEncode(GetDetailUrl(row["Slug"]))).Append("\",");
+                sb.Append("\"image\":\"").Append(JsonEncode(GetThumbnailUrl(row["Thumbnail"]))).Append("\"");
+                sb.Append("}");
+            }
+            sb.Append("]");
+            return sb.ToString();
+        }
+        private string GetString(DataRow row, string columnName)
+        {
+            if (row == null || row.Table == null || !row.Table.Columns.Contains(columnName) || row[columnName] == DBNull.Value)
+                return string.Empty;
+            return Convert.ToString(row[columnName]);
+        }
+        private string GetDateDisplay(object dateObj)
+        {
+            if (dateObj == null || dateObj == DBNull.Value)
+                return string.Empty;
+            try
+            {
+                return Convert.ToDateTime(dateObj).ToString("dd/MM/yyyy");
+            }
+            catch
+            {
+                return string.Empty;
+            }
+        }
+        private string GetDetailUrl(object slugObj)
+        {
+            if (slugObj == null || slugObj == DBNull.Value)
+                return "/chi-tiet-tin";
+            string slug = Convert.ToString(slugObj).Trim();
+            if (string.IsNullOrEmpty(slug))
+                return "/chi-tiet-tin";
+            return "/" + HttpUtility.UrlPathEncode(slug);
+        }
+        private string GetThumbnailUrl(object thumbObj)
+        {
+            string url = (thumbObj != null && thumbObj != DBNull.Value) ? Convert.ToString(thumbObj).Trim() : string.Empty;
+            return string.IsNullOrEmpty(url) ? "/Media/Images/tin-tuc-2.jpg" : url;
+        }
+        private string JsonEncode(string value)
+        {
+            if (string.IsNullOrEmpty(value))
+                return string.Empty;
+            return value.Replace("\\", "\\\\").Replace("\"", "\\\"").Replace("\r", "\\r").Replace("\n", "\\n");
         }
     }
 }
