using System;
using System.Data;
using System.Web;
using System.Web.UI;
using DCore;
using InformationWebObject;
namespace InformationWeb
{
    public partial class Router : Page
    {
        private const string ListControlPath = "~/Controls/InfoSection/News/NewsList.ascx";
        private const string DetailControlPath = "~/Controls/InfoSection/News/NewsDetail.ascx";
        // Phân giải URL trước khi tạo control.
        protected override void OnInit(EventArgs e)
        {
            base.OnInit(e);
            ResolveAndLoad();
        }
        // Chọn control danh sách hoặc chi tiết.
        private void ResolveAndLoad()
        {
            string slug = GetRequestSlug();
            if (string.IsNullOrEmpty(slug))
            {
                ShowNotFound();
                return;
            }
            string[] segments = slug.Split(new char[] { '/' }, StringSplitOptions.RemoveEmptyEntries);
            if (segments.Length == 0 || !AreSafeSegments(segments))
            {
                ShowNotFound();
                return;
            }
            try
            {
                if (segments.Length == 1 && CategoryExists(segments[0]))
                {
                    LoadDynamicControl(ListControlPath, segments[0]);
                    return;
                }
                string informationSlug = segments[segments.Length - 1];
                if (PostExists(informationSlug))
                {
                    LoadDynamicControl(DetailControlPath, informationSlug);
                    return;
                }
                ShowNotFound();
            }
            catch (Exception ex)
            {
                LogError("Router: Lỗi phân giải đường dẫn", ex);
                ShowNotFound();
            }
        }
        // Lấy slug đã rewrite từ request.
        private string GetRequestSlug()
        {
            string slug = Convert.ToString(Request.QueryString["slug"] ?? string.Empty).Trim();
            slug = HttpUtility.UrlDecode(slug).Replace("\\", "/").Trim('/');
            while (slug.IndexOf("//", StringComparison.Ordinal) >= 0)
            {
                slug = slug.Replace("//", "/");
            }
            return slug;
        }
        // Kiểm tra toàn bộ đoạn slug an toàn.
        private bool AreSafeSegments(string[] segments)
        {
            for (int index = 0; index < segments.Length; index++)
            {
                if (!IsSafeSlug(segments[index]))
                {
                    return false;
                }
            }
            return true;
        }
        // Kiểm tra một slug chỉ gồm ký tự hợp lệ.
        private bool IsSafeSlug(string slug)
        {
            if (string.IsNullOrEmpty(slug) || slug.Length > 200)
            {
                return false;
            }
            for (int index = 0; index < slug.Length; index++)
            {
                char character = slug[index];
                bool isLetterOrDigit = (character >= 'a' && character <= 'z') || (character >= 'A' && character <= 'Z') || (character >= '0' && character <= '9');
                if (!isLetterOrDigit && character != '-')
                {
                    return false;
                }
            }
            return true;
        }
        // Kiểm tra slug danh mục trong SQL.
        private bool CategoryExists(string slug)
        {
            INFO_Information information = new INFO_Information();
            DataTable dataTable = information.GetDataTable("INFO_Information_Router_GetCategoryBySlug", "@CategoryLink", slug);
            return dataTable != null && dataTable.Rows.Count > 0;
        }
        // Kiểm tra slug bài viết trong SQL.
        private bool PostExists(string slug)
        {
            INFO_Information information = new INFO_Information();
            DataTable dataTable = information.GetDataTable("INFO_Information_Router_GetPostBySlug", "@InformationLink", slug);
            return dataTable != null && dataTable.Rows.Count > 0;
        }
        // Nạp control và truyền slug nội bộ.
        private void LoadDynamicControl(string controlPath, string slug)
        {
            Context.Items["routerSlug"] = slug;
            Context.Items["slug"] = slug;
            phMain.Controls.Clear();
            phMain.Controls.Add(LoadControl(controlPath));
            pnlNotFound.Visible = false;
        }
        // Hiển thị nội dung không tìm thấy.
        private void ShowNotFound()
        {
            Response.StatusCode = 404;
            Response.TrySkipIisCustomErrors = true;
            phMain.Controls.Clear();
            pnlNotFound.Visible = true;
        }
        // Ghi lỗi router, không lộ lỗi ra UI.
        private void LogError(string message, Exception ex)
        {
            try
            {
                new SystemError(SystemConfig.ConnectionString, message, ex);
            }
            catch
            {
            }
        }
    }
}

