using System;
using System.Data;
using System.Web;
using System.Web.UI;
using System.Web.UI.WebControls;
using DCore;
using InformationWebObject;
namespace InformationWeb.Controls.InfoSection
{
    public partial class DetailList : System.Web.UI.UserControl
    {
        private const string CategorySlugTinTuc = "tin-tuc";
        private const string CategorySlugNghe = "danh-muc-nghe";
        private const int ListTop = 50;
        private const int SidebarRecentTop = 5;
        private const int SidebarTagTop = 7;
        private string currentCategorySlug = CategorySlugTinTuc;
        // Trả URL trang danh sách cũ cho form tìm kiếm.
        public string ListPageBaseUrl
        {
            get { return ResolveUrl("~/Pages/InfoSection/InfoLisst.aspx"); }
        }
        // Nạp danh sách và sidebar lần đầu.
        protected void Page_Load(object sender, EventArgs e)
        {
            if (IsPostBack)
            {
                return;
            }
            currentCategorySlug = GetCategorySlug();
            string categoryTitle = GetCategoryDisplayName(currentCategorySlug);
            litCategoryTitle.Text = HttpUtility.HtmlEncode(categoryTitle);
            litBreadcrumbCateName.Text = HttpUtility.HtmlEncode(categoryTitle);
            linkBreadcrumbDanhMucTin.NavigateUrl = GetListFriendlyUrl(CategorySlugTinTuc);
            if (string.Equals(currentCategorySlug, CategorySlugNghe, StringComparison.OrdinalIgnoreCase))
            {
                BindCareers();
            }
            else
            {
                BindNews(currentCategorySlug);
            }
            BindSidebar();
        }
        // Lấy slug danh mục từ router hoặc query cũ.
        private string GetCategorySlug()
        {
            object routerSlug = Context.Items["routerSlug"];
            string slug = routerSlug == null ? string.Empty : Convert.ToString(routerSlug).Trim();
            if (string.IsNullOrEmpty(slug))
            {
                slug = Convert.ToString(Request["clink"] ?? string.Empty).Trim();
            }
            return string.IsNullOrEmpty(slug) ? CategorySlugTinTuc : slug;
        }
        // Lấy tên danh mục để hiển thị.
        private string GetCategoryDisplayName(string cateSlug)
        {
            if (string.Equals(cateSlug, CategorySlugNghe, StringComparison.OrdinalIgnoreCase))
            {
                return "Ngành nghề";
            }
            try
            {
                INFO_Information information = new INFO_Information();
                DataTable dataTable = information.GetDataTable("INFO_Information_CateList");
                if (dataTable != null)
                {
                    foreach (DataRow row in dataTable.Rows)
                    {
                        if (string.Equals(Convert.ToString(row["Slug"]).Trim(), cateSlug, StringComparison.OrdinalIgnoreCase))
                        {
                            return Convert.ToString(row["CateName"]).Trim();
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                LogError("DetailList: Lỗi lấy tên danh mục", ex);
            }
            return "Tin tức";
        }
        // Bind bài viết theo slug danh mục.
        private void BindNews(string cateSlug)
        {
            try
            {
                INFO_Information information = new INFO_Information();
                DataTable dataTable = information.GetDataTable("INFO_Information_List_ByCateSlug", "@CateSlug", cateSlug, "@Top", ListTop);
                rptList.DataSource = dataTable;
                rptList.DataBind();
            }
            catch (Exception ex)
            {
                LogError("DetailList: Lỗi load danh sách tin", ex);
            }
        }
        // Bind danh sách ngành nghề cũ.
        private void BindCareers()
        {
            try
            {
                INFO_Information information = new INFO_Information();
                DataTable sourceTable = information.GetDataTable("INFO_Career_Search", "@Keyword", null, "@IsActived", true);
                DataTable viewTable = CreateCareerViewTable();
                if (sourceTable != null)
                {
                    foreach (DataRow row in sourceTable.Rows)
                    {
                        viewTable.Rows.Add(row["InformationLink"], row["CareerName"], row["Thumbnail"], "Ngành nghề", CategorySlugNghe, string.Empty, DBNull.Value, string.Empty);
                    }
                }
                rptList.DataSource = viewTable;
                rptList.DataBind();
            }
            catch (Exception ex)
            {
                LogError("DetailList: Lỗi load danh sách nghề", ex);
            }
        }
        // Tạo bảng hiển thị chung cho ngành nghề.
        private DataTable CreateCareerViewTable()
        {
            DataTable dataTable = new DataTable();
            dataTable.Columns.Add("Slug", typeof(string));
            dataTable.Columns.Add("Title", typeof(string));
            dataTable.Columns.Add("Thumbnail", typeof(string));
            dataTable.Columns.Add("CateName", typeof(string));
            dataTable.Columns.Add("CateSlug", typeof(string));
            dataTable.Columns.Add("Description", typeof(string));
            dataTable.Columns.Add("CreatedDate", typeof(DateTime));
            dataTable.Columns.Add("Author", typeof(string));
            return dataTable;
        }
        // Bind danh mục, bài mới và thẻ.
        private void BindSidebar()
        {
            try
            {
                INFO_Information information = new INFO_Information();
                DataTable categoryTable = information.GetDataTable("INFO_Information_CateList");
                rptCategories.DataSource = categoryTable;
                rptCategories.DataBind();
                DataTable recentTable = information.GetDataTable("INFO_Information_List_NotCareer", "@Top", SidebarRecentTop, "@ExcludeCategoryId", DBNull.Value);
                rptRecent.DataSource = recentTable;
                rptRecent.DataBind();
                BindSidebarTagCloud(information.GetDataTable("INFO_Information_TagCloud", "@Top", SidebarTagTop));
            }
            catch (Exception ex)
            {
                LogError("DetailList: Lỗi load sidebar", ex);
            }
        }
        // Tạo link cho danh sách thẻ.
        private void BindSidebarTagCloud(DataTable dataTable)
        {
            phTagCloud.Controls.Clear();
            if (dataTable == null)
            {
                return;
            }
            foreach (DataRow row in dataTable.Rows)
            {
                string tagName = Convert.ToString(row["TagName"]).Trim();
                if (string.IsNullOrEmpty(tagName))
                {
                    continue;
                }
                HyperLink link = new HyperLink();
                link.Text = HttpUtility.HtmlEncode(tagName);
                link.NavigateUrl = ListPageBaseUrl + "?tag=" + HttpUtility.UrlEncode(tagName);
                phTagCloud.Controls.Add(link);
                phTagCloud.Controls.Add(new LiteralControl(" "));
            }
        }
        // Tạo URL chi tiết theo danh mục hiện tại.
        public string GetDetailUrl(object slugObj)
        {
            string slug = GetStringValue(slugObj);
            if (string.IsNullOrEmpty(slug))
            {
                return "#";
            }
            if (string.Equals(currentCategorySlug, CategorySlugNghe, StringComparison.OrdinalIgnoreCase))
            {
                return "/nghe/" + HttpUtility.UrlPathEncode(slug);
            }
            return "/" + HttpUtility.UrlPathEncode(currentCategorySlug) + "/" + HttpUtility.UrlPathEncode(slug);
        }
        // Tạo URL chi tiết theo slug bài và danh mục.
        public string GetDetailUrl(object cateSlugObj, object slugObj)
        {
            string cateSlug = GetStringValue(cateSlugObj);
            string slug = GetStringValue(slugObj);
            if (string.IsNullOrEmpty(slug))
            {
                return "#";
            }
            if (string.Equals(cateSlug, CategorySlugNghe, StringComparison.OrdinalIgnoreCase))
            {
                return "/nghe/" + HttpUtility.UrlPathEncode(slug);
            }
            return "/" + HttpUtility.UrlPathEncode(cateSlug) + "/" + HttpUtility.UrlPathEncode(slug);
        }
        // Tạo URL danh mục thân thiện.
        public string GetListUrl(object cateSlugObj)
        {
            return GetListFriendlyUrl(GetStringValue(cateSlugObj));
        }
        // Tạo URL danh mục từ chuỗi.
        public string GetListFriendlyUrl(string slug)
        {
            if (string.IsNullOrEmpty(slug))
            {
                return ListPageBaseUrl;
            }
            if (string.Equals(slug, CategorySlugNghe, StringComparison.OrdinalIgnoreCase))
            {
                return "/danh-muc-nghe";
            }
            return "/" + HttpUtility.UrlPathEncode(slug);
        }
        // Tạo URL danh mục từ dữ liệu bind.
        public string GetListFriendlyUrl(object cateSlugObj)
        {
            return GetListFriendlyUrl(GetStringValue(cateSlugObj));
        }
        // Lấy ảnh đại diện hoặc ảnh mặc định.
        public string GetThumbnailUrl(object thumbObj)
        {
            string url = GetStringValue(thumbObj);
            return string.IsNullOrEmpty(url) ? "/assets/images/tt-1.png" : url;
        }
        // Lấy ngày dạng số.
        public string GetDateDay(object dateObj)
        {
            return FormatDate(dateObj, "dd");
        }
        // Lấy tháng và năm.
        public string GetDateMonthYear(object dateObj)
        {
            return FormatDate(dateObj, "MMM, yyyy");
        }
        // Lấy ngày đầy đủ.
        public string GetDateDisplay(object dateObj)
        {
            return FormatDate(dateObj, "dd/MM/yyyy");
        }
        // Lấy ngày hoặc dấu gạch.
        public string GetDateDisplayOrDash(object dateObj)
        {
            string value = GetDateDisplay(dateObj);
            return string.IsNullOrEmpty(value) ? "—" : value;
        }
        // Lấy tác giả hoặc dấu gạch.
        public string GetAuthorDisplay(object authorObj)
        {
            string value = Enc(authorObj);
            return string.IsNullOrEmpty(value) ? "—" : value;
        }
        // Định dạng ngày an toàn.
        private string FormatDate(object dateObj, string format)
        {
            if (dateObj == null || dateObj == DBNull.Value)
            {
                return string.Empty;
            }
            DateTime date;
            return DateTime.TryParse(Convert.ToString(dateObj), out date) ? date.ToString(format) : string.Empty;
        }
        // Lấy chuỗi an toàn từ object.
        private string GetStringValue(object value)
        {
            return value == null || value == DBNull.Value ? string.Empty : Convert.ToString(value).Trim();
        }
        // Mã hóa nội dung hiển thị.
        public string Enc(object value)
        {
            return HttpUtility.HtmlEncode(GetStringValue(value));
        }
        // Mã hóa giá trị query string.
        public string UrlEnc(object value)
        {
            return HttpUtility.UrlEncode(GetStringValue(value));
        }
        // Ghi lỗi hệ thống ngắn gọn.
        private void LogError(string message, Exception ex)
        {
            new SystemError(SystemConfig.ConnectionString, message, ex);
        }
    }
}

