        private const string CategorySlugNghe = "danh-muc-nghe";
        private string currentCategorySlug = string.Empty;
        // Trả URL trang danh sách cũ cho form tìm kiếm.
        public string ListPageBaseUrl
        {
            get { return ResolveUrl("~/Pages/InfoSection/InfoLisst.aspx"); }
        }
        // Nạp chi tiết bài viết lần đầu.
        protected void Page_Load(object sender, EventArgs e)
        {
            if (IsPostBack)
            {
                return;
            }
            LoadDetail();
        }
        // Lấy slug bài viết từ router hoặc query cũ.
        private string GetInformationSlug()
        {
            object routerSlug = Context.Items["routerSlug"];
            string slug = routerSlug == null ? string.Empty : Convert.ToString(routerSlug).Trim();
            if (string.IsNullOrEmpty(slug))
            {
                slug = Convert.ToString(Request["ilink"] ?? string.Empty).Trim();
            }
            return slug;
        }
        // Nạp dữ liệu bài viết và sidebar.
        private void LoadDetail()
        {
            try
            {
                string slug = GetInformationSlug();
                if (string.IsNullOrEmpty(slug))
                {
                    ShowNotFound();
                    BindSidebarOnly();
                    return;
                }
                INFO_Information information = new INFO_Information();
                DataTable detailTable = information.GetDataTable("INFO_Information_DetailBySlug", "@Slug", slug);
                if (detailTable == null || detailTable.Rows.Count == 0)
                {
                    ShowNotFound();
                    BindSidebarOnly();
                    return;
                }
                BindDetailRow(detailTable.Rows[0]);
                BindSidebar(information, detailTable.Rows[0]);
            }
            catch (Exception ex)
            {
                LogError("Detail: Lỗi load chi tiết tin", ex);
                ShowNotFound();
                BindSidebarOnly();
            }
        }
        // Gán dữ liệu chi tiết lên giao diện.
        private void BindDetailRow(DataRow row)
        {
            phNotFound.Visible = false;
            phContent.Visible = true;
            currentCategorySlug = GetRowString(row, "CateSlug");
            litTitle.Text = HttpUtility.HtmlEncode(GetRowString(row, "Title"));
            string dateText = FormatDate(GetRowValue(row, "CreatedDate"), "dd/MM/yyyy");
            litDate.Text = dateText;
            litDateMeta.Text = dateText;
            string content = GetRowString(row, "ContentHtml");
            if (string.IsNullOrEmpty(content))
            {
                content = "<p>" + HttpUtility.HtmlEncode(GetRowString(row, "Brief")) + "</p>";
            }
            litContent.Text = content;
            string thumbnail = GetRowString(row, "Thumbnail");
            imgWrap.Visible = !string.IsNullOrEmpty(thumbnail);
            imgThumb.ImageUrl = string.IsNullOrEmpty(thumbnail) ? ResolveUrl("~/assets/images/new-1.png") : thumbnail;
            string categoryName = GetRowString(row, "CateName");
            linkCate.NavigateUrl = GetListFriendlyUrl(currentCategorySlug);
            linkCate.Text = HttpUtility.HtmlEncode(string.IsNullOrEmpty(categoryName) ? "Danh mục" : categoryName);
            linkBreadcrumbCate.NavigateUrl = GetListFriendlyUrl(currentCategorySlug);
            linkBreadcrumbCate.Text = HttpUtility.HtmlEncode(string.IsNullOrEmpty(categoryName) ? "Chi tiết" : categoryName);
            linkDate.HRef = GetDetailUrl(currentCategorySlug, GetRowString(row, "Slug"));
            BindTags(GetRowString(row, "TagText"), phTag, currentCategorySlug);
        }
        // Hiển thị trạng thái không tìm thấy.
        private void ShowNotFound()
        {
            phNotFound.Visible = true;
            phContent.Visible = false;
            linkBreadcrumbCate.NavigateUrl = GetListFriendlyUrl("tin-tuc");
            linkBreadcrumbCate.Text = "Chi tiết";
        }
        // Bind danh mục, bài liên quan và thẻ.
        private void BindSidebar(INFO_Information information, DataRow currentRow)
        {
            BindCategories(information);
            long informationId = GetRowLong(currentRow, "ID");
            long categoryId = GetRowLong(currentRow, "CateID");
            DataTable relatedTable = information.GetDataTable("INFO_Information_Related", "@InformationID", informationId, "@CateID", categoryId, "@Top", RelatedTop);
            rptRelated.DataSource = relatedTable;
            rptRelated.DataBind();
            BindSidebarTagCloud(information.GetDataTable("INFO_Information_TagCloud", "@Top", TagTop));
        }
        // Bind sidebar khi bài không tồn tại.
        private void BindSidebarOnly()
        {
            try
            {
                INFO_Information information = new INFO_Information();
                BindCategories(information);
                BindSidebarTagCloud(information.GetDataTable("INFO_Information_TagCloud", "@Top", TagTop));
            }
            catch (Exception ex)
            {
                LogError("Detail: Lỗi load sidebar", ex);
            }
        }
        // Bind danh mục tin tức.
        private void BindCategories(INFO_Information information)
        {
            rptCategories.DataSource = information.GetDataTable("INFO_Information_CateList");
            rptCategories.DataBind();
        }
        // Tạo link cho thẻ của bài viết.
        private void BindTags(string tagText, PlaceHolder placeHolder, string cateSlug)
        {
            placeHolder.Controls.Clear();
            string[] tags = SplitTags(tagText);
            for (int index = 0; index < tags.Length; index++)
            {
                HyperLink link = new HyperLink();
                link.Text = HttpUtility.HtmlEncode(tags[index]);
                link.NavigateUrl = ListPageBaseUrl + "?clink=" + HttpUtility.UrlEncode(cateSlug) + "&tag=" + HttpUtility.UrlEncode(tags[index]);
                placeHolder.Controls.Add(link);
                placeHolder.Controls.Add(new LiteralControl(" "));
            }
        }
        // Tạo link cho thẻ sidebar.
        private void BindSidebarTagCloud(DataTable dataTable)
        {
            phSidebarTag.Controls.Clear();
            if (dataTable == null)
            {
                return;
            }
            foreach (DataRow row in dataTable.Rows)
            {
                string tagName = Convert.ToString(row["TagName"]).Trim();
                if (string.IsNullOrEmpty(tagName))
                {
                    continue;
                }
                HyperLink link = new HyperLink();
                link.Text = HttpUtility.HtmlEncode(tagName);
                link.NavigateUrl = ListPageBaseUrl + "?tag=" + HttpUtility.UrlEncode(tagName);
                phSidebarTag.Controls.Add(link);
                phSidebarTag.Controls.Add(new LiteralControl(" "));
            }
        }
        // Tách chuỗi thẻ thành mảng sạch.
        private string[] SplitTags(string tagText)
        {
            if (string.IsNullOrEmpty(tagText))
            {
                return new string[0];
            }
            string[] source = tagText.Split(new char[] { ',', ';' }, StringSplitOptions.RemoveEmptyEntries);
            System.Collections.Generic.List<string> tags = new System.Collections.Generic.List<string>();
            for (int index = 0; index < source.Length; index++)
            {
                string tag = source[index].Trim();
                if (!string.IsNullOrEmpty(tag))
                {
                    tags.Add(tag);
                }
            }
            return tags.ToArray();
        }
        // Tạo URL danh mục thân thiện.
        public string GetListFriendlyUrl(object cateSlugObj)
        {
            string slug = GetStringValue(cateSlugObj);
            if (string.IsNullOrEmpty(slug))
            {
                return ListPageBaseUrl;
            }
            if (string.Equals(slug, CategorySlugNghe, StringComparison.OrdinalIgnoreCase))
            {
                return "/danh-muc-nghe";
            }
            return "/" + HttpUtility.UrlPathEncode(slug);
        }
        // Tạo URL chi tiết theo danh mục và bài.
        public string GetDetailUrl(object cateSlugObj, object slugObj)
        {
            string cateSlug = GetStringValue(cateSlugObj);
            string slug = GetStringValue(slugObj);
            if (string.IsNullOrEmpty(slug))
            {
                return "#";
            }
            if (string.Equals(cateSlug, CategorySlugNghe, StringComparison.OrdinalIgnoreCase))
            {
                return "/nghe/" + HttpUtility.UrlPathEncode(slug);
            }
            return "/" + HttpUtility.UrlPathEncode(cateSlug) + "/" + HttpUtility.UrlPathEncode(slug);
        }
        // Tạo URL chi tiết theo danh mục hiện tại.
        public string GetDetailUrl(object slugObj)
        {
            return GetDetailUrl(currentCategorySlug, slugObj);
        }
        // Mã hóa nội dung hiển thị.
        public string Enc(object value)
        {
            return HttpUtility.HtmlEncode(GetStringValue(value));
        }
        // Lấy chuỗi an toàn từ object.
        private string GetStringValue(object value)
        {
            return value == null || value == DBNull.Value ? string.Empty : Convert.ToString(value).Trim();
        }
        // Lấy giá trị cột an toàn.
        private object GetRowValue(DataRow row, string columnName)
        {
            return row.Table.Columns.Contains(columnName) ? row[columnName] : DBNull.Value;
        }
        // Lấy chuỗi cột an toàn.
        private string GetRowString(DataRow row, string columnName)
        {
            return GetStringValue(GetRowValue(row, columnName));
        }
        // Lấy số nguyên dài an toàn.
        private long GetRowLong(DataRow row, string columnName)
        {
            long value;
            return long.TryParse(GetRowString(row, columnName), out value) ? value : 0;
        }
        // Định dạng ngày an toàn.
        private string FormatDate(object dateObj, string format)
        {
            DateTime date;
            return dateObj != null && dateObj != DBNull.Value && DateTime.TryParse(Convert.ToString(dateObj), out date) ? date.ToString(format) : string.Empty;
        }
        // Ghi lỗi hệ thống ngắn gọn.
        private void LogError(string message, Exception ex)
        {
            new SystemError(SystemConfig.ConnectionString, message, ex);
        }
    }
}

