using System;
using System.Configuration;
using System.Data;
using System.Data.SqlClient;
using DCore;
using InformationWeb.Models;
namespace InformationWeb.DataAccess
{
    public class AdmissionRegistrationDAL
    {
        private readonly string connectionString;
        // Lấy chuỗi kết nối từ Web.config.
        public AdmissionRegistrationDAL()
        {
            ConnectionStringSettings settings = ConfigurationManager.ConnectionStrings["ConnectionString"];
            if (settings == null || string.IsNullOrEmpty(settings.ConnectionString))
                throw new InvalidOperationException("Không tìm thấy cấu hình kết nối dữ liệu.");
            connectionString = settings.ConnectionString;
        }
        // Lấy danh sách ngành đang hoạt động.
        public DataTable GetCareers()
        {
            try
            {
                using (SqlConnection connection = new SqlConnection(connectionString))
                using (SqlCommand command = new SqlCommand("INFO_Career_Search", connection))
                using (SqlDataAdapter adapter = new SqlDataAdapter(command))
                {
                    command.CommandType = CommandType.StoredProcedure;
                    command.Parameters.AddWithValue("@Keyword", DBNull.Value);
                    command.Parameters.AddWithValue("@IsActived", true);
                    DataTable dataTable = new DataTable();
                    adapter.Fill(dataTable);
                    return dataTable;
                }
            }
            catch (Exception ex)
            {
                new SystemError(SystemConfig.ConnectionString, "AdmissionRegistrationDAL: Lỗi lấy danh sách ngành", ex);
                throw;
            }
        }
        // Lưu hồ sơ đăng ký tuyển sinh.
        public long Add(AdmissionRegistrationModel model)
        {
            try
            {
                using (SqlConnection connection = new SqlConnection(connectionString))
                using (SqlCommand command = new SqlCommand("CRM_RegisterInfo_Admission_ADD", connection))
                {
                    command.CommandType = CommandType.StoredProcedure;
                    command.Parameters.AddWithValue("@Fullname", model.FullName);
                    command.Parameters.AddWithValue("@Gender", model.Gender);
                    command.Parameters.AddWithValue("@BirthDay", model.BirthDate.Day);
                    command.Parameters.AddWithValue("@BirthMonth", model.BirthDate.Month);
                    command.Parameters.AddWithValue("@BirthYear", model.BirthDate.Year);
                    command.Parameters.AddWithValue("@BirthDateText", model.BirthDate.ToString("yyyy-MM-dd"));
                    command.Parameters.AddWithValue("@IdentityNumber", model.IdentityNumber);
                    command.Parameters.AddWithValue("@BirthPlace", GetDbValue(model.BirthPlace));
                    command.Parameters.AddWithValue("@Ethnicity", GetDbValue(model.Ethnicity));
                    command.Parameters.AddWithValue("@Address", model.Address);
                    command.Parameters.AddWithValue("@Email", model.Email);
                    command.Parameters.AddWithValue("@Phone", model.Phone);
                    command.Parameters.AddWithValue("@CareerID", model.CareerID);
                    command.Parameters.AddWithValue("@CareerName", model.CareerName);
                    command.Parameters.AddWithValue("@TrainingLevel", GetDbValue(model.TrainingLevel));
                    command.Parameters.AddWithValue("@Description", GetDbValue(model.Description));
                    command.Parameters.AddWithValue("@IdentityFilePath", GetDbValue(model.IdentityFilePath));
                    command.Parameters.AddWithValue("@TranscriptFilePath", GetDbValue(model.TranscriptFilePath));
                    command.Parameters.AddWithValue("@GraduationFilePath", GetDbValue(model.GraduationFilePath));
                    command.Parameters.AddWithValue("@CreatedUser", "website");
                    connection.Open();
                    object result = command.ExecuteScalar();
                    return result == null || result == DBNull.Value ? 0 : Convert.ToInt64(result);
                }
            }
            catch (Exception ex)
            {
                new SystemError(SystemConfig.ConnectionString, "AdmissionRegistrationDAL: Lỗi lưu hồ sơ tuyển sinh", ex);
                throw;
            }
        }
        // Đổi chuỗi rỗng thành null SQL.
        private object GetDbValue(string value)
        {
            return string.IsNullOrEmpty(value) ? (object)DBNull.Value : value;
        }
    }
}

using System;
using System.Collections.Generic;
using System.Data;
using System.Net.Mail;
using System.Text.RegularExpressions;
using InformationWeb.DataAccess;
using InformationWeb.Models;
namespace InformationWeb.BusinessLogic
{
    public class AdmissionRegistrationBLL
    {
        private readonly AdmissionRegistrationDAL admissionRegistrationDAL;
        // Khởi tạo lớp xử lý hồ sơ.
        public AdmissionRegistrationBLL()
        {
            admissionRegistrationDAL = new AdmissionRegistrationDAL();
        }
        // Lấy danh sách ngành từ DAL.
        public DataTable GetCareers()
        {
            return admissionRegistrationDAL.GetCareers();
        }
        // Kiểm tra dữ liệu hồ sơ.
        public bool Validate(AdmissionRegistrationModel model, out string message)
        {
            List<string> errors = new List<string>();
            if (string.IsNullOrEmpty(model.FullName)) errors.Add("Vui lòng nhập họ và tên.");
            else if (model.FullName.Length > 50) errors.Add("Họ và tên không vượt quá 50 ký tự.");
            if (model.BirthDate == DateTime.MinValue) errors.Add("Ngày sinh không hợp lệ.");
            else if (model.BirthDate.Date >= DateTime.Today) errors.Add("Ngày sinh phải nhỏ hơn ngày hiện tại.");
            if (string.IsNullOrEmpty(model.IdentityNumber) || !Regex.IsMatch(model.IdentityNumber, "^(\\d{9}|\\d{12})$")) errors.Add("CMND/CCCD phải gồm 9 hoặc 12 chữ số.");
            if (string.IsNullOrEmpty(model.Address)) errors.Add("Vui lòng nhập địa chỉ thường trú.");
            else if (model.Address.Length > 1000) errors.Add("Địa chỉ không vượt quá 1000 ký tự.");
            if (!IsValidPhone(model.Phone)) errors.Add("Số điện thoại không hợp lệ.");
            if (!IsValidEmail(model.Email)) errors.Add("Email không hợp lệ.");
            if (model.CareerID <= 0 || string.IsNullOrEmpty(model.CareerName)) errors.Add("Vui lòng chọn ngành đăng ký.");
            if (!string.IsNullOrEmpty(model.Description) && model.Description.Length > 500) errors.Add("Ghi chú không vượt quá 500 ký tự.");
            message = string.Join(" ", errors.ToArray());
            return errors.Count == 0;
        }
        // Lưu hồ sơ hợp lệ.
        public long Add(AdmissionRegistrationModel model)
        {
            return admissionRegistrationDAL.Add(model);
        }
        // Kiểm tra định dạng điện thoại.
        private bool IsValidPhone(string phone)
        {
            if (string.IsNullOrEmpty(phone) || phone.Length > 20) return false;
            string digits = Regex.Replace(phone, "[^0-9]", string.Empty);
            return digits.Length >= 9 && digits.Length <= 15;
        }
        // Kiểm tra định dạng email.
        private bool IsValidEmail(string email)
        {
            if (string.IsNullOrEmpty(email) || email.Length > 100) return false;
            try
            {
                MailAddress address = new MailAddress(email);
                return string.Equals(address.Address, email, StringComparison.OrdinalIgnoreCase);
            }
            catch
            {
                return false;
            }
        }
    }
}

using System;
using System.Collections.Generic;
using System.IO;
using System.Web;
namespace InformationWeb.Helpers
{
    public class AdmissionUploadFile
    {
        public string TempPath { get; set; }
        public string FinalPath { get; set; }
        public string LogicalPath { get; set; }
    }
    public static class AdmissionUploadHelper
    {
        private const int MaxFileSize = 5 * 1024 * 1024;
        private static readonly string[] AllowedExtensions = { ".jpg", ".jpeg", ".png", ".pdf" };
        // Kiểm tra file trước khi lưu.
        public static bool Validate(HttpPostedFile file, out string message)
        {
            message = string.Empty;
            if (file == null || file.ContentLength <= 0) return true;
            string extension = Path.GetExtension(Path.GetFileName(file.FileName));
            if (string.IsNullOrEmpty(extension) || Array.IndexOf(AllowedExtensions, extension.ToLowerInvariant()) < 0)
            {
                message = "File chỉ chấp nhận định dạng JPG, JPEG, PNG hoặc PDF.";
                return false;
            }
            if (file.ContentLength > MaxFileSize)
            {
                message = "Mỗi file tải lên không được vượt quá 5 MB.";
                return false;
            }
            return true;
        }
        // Lưu file vào thư mục tạm.
        public static AdmissionUploadFile SaveTemporary(HttpPostedFile file, HttpServerUtility server)
        {
            if (file == null || file.ContentLength <= 0) return null;
            string extension = Path.GetExtension(Path.GetFileName(file.FileName)).ToLowerInvariant();
            string fileName = Guid.NewGuid().ToString("N") + extension;
            string year = DateTime.Now.ToString("yyyy");
            string month = DateTime.Now.ToString("MM");
            string tempDirectory = server.MapPath("~/App_Data/AdmissionTemp");
            string finalDirectory = server.MapPath(String.Format("~/Media/Data/Admission/{0}/{1}", year, month));
            if (!Directory.Exists(tempDirectory)) Directory.CreateDirectory(tempDirectory);
            if (!Directory.Exists(finalDirectory)) Directory.CreateDirectory(finalDirectory);
            AdmissionUploadFile uploadFile = new AdmissionUploadFile();
            uploadFile.TempPath = Path.Combine(tempDirectory, fileName);
            uploadFile.FinalPath = Path.Combine(finalDirectory, fileName);
            uploadFile.LogicalPath = String.Format("/Media/Data/Admission/{0}/{1}/{2}", year, month, fileName);
            file.SaveAs(uploadFile.TempPath);
            return uploadFile;
        }
        // Chuyển file sang thư mục chính.
        public static void Commit(IEnumerable<AdmissionUploadFile> files)
        {
            foreach (AdmissionUploadFile file in files)
            {
                if (file != null && File.Exists(file.TempPath)) File.Move(file.TempPath, file.FinalPath);
            }
        }
        // Xóa file khi thao tác lỗi.
        public static void Cleanup(IEnumerable<AdmissionUploadFile> files)
        {
            foreach (AdmissionUploadFile file in files)
            {
                if (file == null) continue;
                if (File.Exists(file.TempPath)) File.Delete(file.TempPath);
                if (File.Exists(file.FinalPath)) File.Delete(file.FinalPath);
            }
        }
    }
}

using System;
using System.Collections.Generic;
using System.Data;
using System.Globalization;
using System.Web;
using System.Web.UI;
using System.Web.UI.WebControls;
using DCore;
using InformationWeb.BusinessLogic;
using InformationWeb.Helpers;
using InformationWeb.Models;
namespace InformationWeb.Controls.InfoSection
{
    public partial class DangKyTuyensinh : System.Web.UI.UserControl
    {
        private readonly AdmissionRegistrationBLL admissionRegistrationBLL = new AdmissionRegistrationBLL();
        // Nạp danh sách ngành lần đầu.
        protected void Page_Load(object sender, EventArgs e)
        {
            if (IsPostBack) return;
            BindCareers();
        }
        // Bind ngành đào tạo từ SQL.
        private void BindCareers()
        {
            try
            {
                DataTable dataTable = admissionRegistrationBLL.GetCareers();
                ddlNganhDangKy.Items.Clear();
                ddlNganhDangKy.Items.Add(new ListItem("-- Chọn ngành đào tạo --", string.Empty));
                if (dataTable == null || dataTable.Rows.Count == 0) return;
                ddlNganhDangKy.DataSource = dataTable;
                ddlNganhDangKy.DataTextField = "CareerName";
                ddlNganhDangKy.DataValueField = "CareerID";
                ddlNganhDangKy.DataBind();
                ddlNganhDangKy.Items.Insert(0, new ListItem("-- Chọn ngành đào tạo --", string.Empty));
            }
            catch (Exception ex)
            {
                new SystemError(SystemConfig.ConnectionString, "DangKyTuyensinh: Lỗi load ngành đào tạo", ex);
                ShowMessage("Không thể tải danh sách ngành. Vui lòng thử lại sau.");
            }
        }
        // Kiểm tra và lưu hồ sơ đăng ký.
        protected void btnDangKy_Click(object sender, EventArgs e)
        {
            List<AdmissionUploadFile> uploadFiles = new List<AdmissionUploadFile>();
            try
            {
                DateTime birthDate;
                if (!TryParseBirthDate(txtNgaySinh.Text.Trim(), out birthDate)) birthDate = DateTime.MinValue;
                AdmissionRegistrationModel model = CreateModel(birthDate);
                string message;
                if (!admissionRegistrationBLL.Validate(model, out message))
                {
                    ShowMessage(message);
                    return;
                }
                if (!ValidateFiles(out message))
                {
                    ShowMessage(message);
                    return;
                }
                AdmissionUploadFile identityFile = AdmissionUploadHelper.SaveTemporary(fileAnhCanCuoc.PostedFile, Server);
                AdmissionUploadFile transcriptFile = AdmissionUploadHelper.SaveTemporary(fileAnhHocBa.PostedFile, Server);
                AdmissionUploadFile graduationFile = AdmissionUploadHelper.SaveTemporary(fileAnhBangTotNghiep.PostedFile, Server);
                uploadFiles.Add(identityFile);
                uploadFiles.Add(transcriptFile);
                uploadFiles.Add(graduationFile);
                model.IdentityFilePath = identityFile == null ? null : identityFile.LogicalPath;
                model.TranscriptFilePath = transcriptFile == null ? null : transcriptFile.LogicalPath;
                model.GraduationFilePath = graduationFile == null ? null : graduationFile.LogicalPath;
                AdmissionUploadHelper.Commit(uploadFiles);
                long registerInfoID = admissionRegistrationBLL.Add(model);
                if (registerInfoID <= 0)
                {
                    AdmissionUploadHelper.Cleanup(uploadFiles);
                    ShowMessage("Không thể lưu hồ sơ. Vui lòng thử lại sau.");
                    return;
                }
                ClearForm();
                ShowSuccessPopup();
            }
            catch (Exception ex)
            {
                AdmissionUploadHelper.Cleanup(uploadFiles);
                new SystemError(SystemConfig.ConnectionString, "DangKyTuyensinh: Lỗi đăng ký tuyển sinh", ex);
                ShowMessage("Đăng ký chưa thành công. Vui lòng kiểm tra thông tin và thử lại sau.");
            }
        }
        // Tạo dữ liệu hồ sơ từ form.
        private AdmissionRegistrationModel CreateModel(DateTime birthDate)
        {
            AdmissionRegistrationModel model = new AdmissionRegistrationModel();
            model.FullName = txtHoTen.Text.Trim();
            model.BirthDate = birthDate;
            model.Gender = ddlGioiTinh.SelectedValue == "Nam";
            model.IdentityNumber = txtCCCD.Text.Trim();
            model.BirthPlace = txtNoiSinh.Text.Trim();
            model.Ethnicity = txtDanToc.Text.Trim();
            model.Address = txtDiaChi.Text.Trim();
            model.Phone = txtDienThoai.Text.Trim();
            model.Email = txtEmail.Text.Trim();
            long careerID;
            model.CareerID = long.TryParse(ddlNganhDangKy.SelectedValue, out careerID) ? careerID : 0;
            model.CareerName = ddlNganhDangKy.SelectedItem == null || model.CareerID <= 0 ? string.Empty : ddlNganhDangKy.SelectedItem.Text.Trim();
            model.TrainingLevel = ddlHeDaoTao.SelectedItem == null ? string.Empty : ddlHeDaoTao.SelectedItem.Text.Trim();
            model.Description = txtGhiChu.Text.Trim();
            return model;
        }
        // Kiểm tra ngày sinh nhiều định dạng.
        private bool TryParseBirthDate(string value, out DateTime birthDate)
        {
            string[] formats = { "yyyy-MM-dd", "dd/MM/yyyy", "d/M/yyyy" };
            return DateTime.TryParseExact(value, formats, CultureInfo.InvariantCulture, DateTimeStyles.None, out birthDate);
        }
        // Kiểm tra ba file hồ sơ.
        private bool ValidateFiles(out string message)
        {
            HttpPostedFile[] files = { fileAnhCanCuoc.PostedFile, fileAnhHocBa.PostedFile, fileAnhBangTotNghiep.PostedFile };
            for (int i = 0; i < files.Length; i++)
            {
                if (!AdmissionUploadHelper.Validate(files[i], out message)) return false;
            }
            message = string.Empty;
            return true;
        }
        // Xóa dữ liệu form sau khi lưu.
        private void ClearForm()
        {
            txtHoTen.Text = string.Empty;
            txtNgaySinh.Text = string.Empty;
            ddlGioiTinh.SelectedIndex = 0;
            txtCCCD.Text = string.Empty;
            txtNoiSinh.Text = string.Empty;
            txtDanToc.Text = "Kinh";
            txtDiaChi.Text = string.Empty;
            txtDienThoai.Text = string.Empty;
            txtEmail.Text = string.Empty;
            ddlNganhDangKy.SelectedIndex = 0;
            ddlHeDaoTao.SelectedIndex = 0;
            txtGhiChu.Text = string.Empty;
        }
        // Hiện thông báo lỗi thân thiện.
        private void ShowMessage(string message)
        {
            string script = String.Format("alert('{0}');", EncodeJavaScript(message));
            RegisterScript("DangKyMessage", script);
        }
        // Hiện popup khi lưu thành công.
        private void ShowSuccessPopup()
        {
            const string script = "if(typeof dangkyShowSuccessModal === 'function') dangkyShowSuccessModal();";
            RegisterScript("DangKySuccess", script);
        }
        // Đăng ký script sau postback.
        private void RegisterScript(string key, string script)
        {
            ScriptManager scriptManager = ScriptManager.GetCurrent(Page);
            if (scriptManager != null) ScriptManager.RegisterStartupScript(Page, Page.GetType(), key, script, true);
            else Page.ClientScript.RegisterStartupScript(Page.GetType(), key, script, true);
        }
        // Mã hóa chuỗi cho JavaScript.
        private string EncodeJavaScript(string value)
        {
            if (string.IsNullOrEmpty(value)) return string.Empty;
            return value.Replace("\\", "\\\\").Replace("'", "\\'").Replace("\r", " ").Replace("\n", " ");
        }
    }
}

