                {
                    string sectionCode = GetRowValue(row, "SectionCode");
                    string contentCode = GetRowValue(row, "ContentCode");
                    if (string.Equals(sectionCode, "SectionAbout", StringComparison.OrdinalIgnoreCase) && !string.IsNullOrEmpty(contentCode) && !contentByCode.ContainsKey(contentCode))
                    {
                        contentByCode.Add(contentCode, row);
                    }
                }
