        protected string Num(string contentCode)
        {
            string value = GetValue(contentCode, "NumberValue");
            decimal number;
            if (!decimal.TryParse(value, out number))
            {
                return value;
            }
            return number == decimal.Truncate(number) ? number.ToString("0") : number.ToString("0.############################");
        }
