        public bool AddAdmission()
        {
            if (!bolIsExistIData)
                objIData = DCore.Data.CreateData();
            try
            {
                objIData.CreateNewStoredProcedure("CRM_RegisterInfo_Admission_ADD");
                objIData.AddParameter("@Fullname", strFullName);
