                objIData.AddParameter("@TrainingLevel", strTrainingLevel);
                objIData.AddParameter("@Description", strDescription);
                objIData.AddParameter("@IdentityFilePath", strIdentityFilePath);
                objIData.AddParameter("@TranscriptFilePath", strTranscriptFilePath);
                objIData.AddParameter("@GraduationFilePath", strGraduationFilePath);
                objIData.AddParameter("@CreatedUser", strCreatedUser);
