private AdmissionRegistrationModel CreateModel(DateTime birthDate)
{
    AdmissionRegistrationModel model = new AdmissionRegistrationModel();
    model.FullName = txtHoTen.Text.Trim();
    model.BirthDate = birthDate;
    model.Gender = ddlGioiTinh.SelectedValue == "Nam";
    model.IdentityNumber = txtCCCD.Text.Trim();
    model.BirthPlace = txtNoiSinh.Text.Trim();
    model.Ethnicity = txtDanToc.Text.Trim();
    model.Address = txtDiaChi.Text.Trim();
    model.Phone = txtDienThoai.Text.Trim();
    model.Email = txtEmail.Text.Trim();
    long careerID;
    model.CareerID = long.TryParse(ddlNganhDangKy.SelectedValue, out careerID) ? careerID : 0;
    model.CareerName = ddlNganhDangKy.SelectedItem == null || model.CareerID <= 0 ? string.Empty : ddlNganhDangKy.SelectedItem.Text.Trim();
    model.TrainingLevel = ddlHeDaoTao.SelectedItem == null ? string.Empty : ddlHeDaoTao.SelectedItem.Text.Trim();
    model.Description = txtGhiChu.Text.Trim();
    return model;
}

